script:
const tripDays = [
  {
    day: 'DAY 1',
    title: '湖滨初见',
    mood: '轻松抵达',
    route: '湖滨步行街 · 西湖音乐喷泉 · 南山路',
    duration: '约 5 小时',
    transport: '步行 6.2 km',
  },
  {
    day: 'DAY 2',
    title: '西湖经典',
    mood: '环湖漫游',
    route: '曲院风荷 · 苏堤 · 花港观鱼 · 雷峰塔',
    duration: '约 8 小时',
    transport: '骑行 + 步行',
  },
  {
    day: 'DAY 3',
    title: '禅意山林',
    mood: '早起推荐',
    route: '灵隐寺 · 法喜寺 · 青芝坞',
    duration: '约 7 小时',
    transport: '公交 + 步行',
  },
  {
    day: 'DAY 4',
    title: '宋韵慢游',
    mood: '城市人文',
    route: '小河直街 · 拱宸桥 · 京杭大运河',
    duration: '约 6 小时',
    transport: '地铁 + 水上巴士',
  },
  {
    day: 'DAY 5',
    title: '茶山收尾',
    mood: '清新徒步',
    route: '九溪烟树 · 龙井村 · 中国茶叶博物馆',
    duration: '约 6 小时',
    transport: '徒步 8.5 km',
  },
];

const nodeListeners = [];
let selectedCard;
let selectionStatusRawText;

const backgroundThread = lynx.getJSContext();
const engine = lynx.getEngine();

function createView(pageId, className) {
  const view = __CreateView(pageId);
  __SetClasses(view, className);
  return view;
}

function createText(pageId, value, className) {
  const text = __CreateText(pageId);
  const rawText = __CreateRawText(value);
  __SetClasses(text, className);
  __AppendElement(text, rawText);
  return { text, rawText };
}

function appendText(parent, pageId, value, className) {
  const result = createText(pageId, value, className);
  __AppendElement(parent, result.text);
  return result.rawText;
}

function bindTap(node, handler) {
  const options = {};
  __AddEventListener(node, 'tap', handler, options);
  nodeListeners.push({ node, handler, options });
}

function selectDay(card, item, index) {
  if (selectedCard) {
    __SetClasses(selectedCard, 'day-card');
  }
  selectedCard = card;
  __SetClasses(card, 'day-card day-card-selected');
  __SetAttribute(
    selectionStatusRawText,
    'text',
    '正在生成 ' + item.day + ' · ' + item.title + ' 的行程提示…',
  );
  __FlushElementTree();

  backgroundThread.dispatchEvent({
    type: 'select-trip-day',
    data: { index, day: item.day, title: item.title },
  });
}

function onTripDaySelected(event) {
  if (!selectionStatusRawText || !event.data) return;
  __SetAttribute(selectionStatusRawText, 'text', event.data.message);
  __FlushElementTree();
}

function clearListeners() {
  for (const listener of nodeListeners.splice(0)) {
    __RemoveEventListener(
      listener.node,
      'tap',
      listener.handler,
      listener.options,
    );
  }
  backgroundThread.removeEventListener(
    'trip-day-selected',
    onTripDaySelected,
  );
  engine.removeEventListener('__DestroyLifetime', clearListeners);
}

backgroundThread.addEventListener('trip-day-selected', onTripDaySelected);
engine.addEventListener('__DestroyLifetime', clearListeners);

globalThis.renderPage = function renderPage() {
  const page = __CreatePage('hangzhou-trip', 0);
  const pageId = __GetElementUniqueID(page);
  __SetClasses(page, 'page');

  const scroll = __CreateScrollView(pageId);
  __SetClasses(scroll, 'trip-scroll');
  __SetAttribute(scroll, 'scroll-orientation', 'vertical');
  __SetAttribute(scroll, 'scroll-bar-enable', false);
  __AppendElement(page, scroll);

  const content = createView(pageId, 'trip-content');
  __AppendElement(scroll, content);

  const hero = createView(pageId, 'hero');
  __AppendElement(content, hero);
  __AppendElement(hero, createView(pageId, 'hero-orb-large'));
  const weatherOrb = createView(pageId, 'hero-orb-small');
  __AppendElement(hero, weatherOrb);
  appendText(weatherOrb, pageId, '18°', 'hero-orb-temperature');
  appendText(weatherOrb, pageId, '晴', 'hero-orb-weather');
  appendText(hero, pageId, '5 DAYS · HANGZHOU', 'hero-kicker');
  appendText(hero, pageId, '去杭州，慢慢走', 'hero-title');
  appendText(
    hero,
    pageId,
    '西湖晨雾、寺院钟声与龙井茶香',
    'hero-subtitle',
  );

  const heroMeta = createView(pageId, 'hero-meta');
  const avatar = createView(pageId, 'hero-avatar');
  const metaCopy = createView(pageId, 'hero-meta-copy');
  __AppendElement(hero, heroMeta);
  __AppendElement(heroMeta, avatar);
  appendText(avatar, pageId, '杭', 'hero-avatar-text');
  __AppendElement(heroMeta, metaCopy);
  appendText(metaCopy, pageId, '春日限定路线', 'hero-meta-title');
  appendText(metaCopy, pageId, '适合第一次到杭州的你', 'hero-meta-subtitle');

  const summary = createView(pageId, 'summary-card');
  __AppendElement(content, summary);
  const summaryItems = [
    ['5 天', '行程长度'],
    ['14 处', '风景与人文'],
    ['4.8', '轻松指数'],
  ];
  summaryItems.forEach((item, index) => {
    if (index > 0) {
      __AppendElement(summary, createView(pageId, 'summary-divider'));
    }
    const summaryItem = createView(pageId, 'summary-item');
    __AppendElement(summary, summaryItem);
    appendText(summaryItem, pageId, item[0], 'summary-value');
    appendText(summaryItem, pageId, item[1], 'summary-label');
  });

  const notice = createView(pageId, 'notice');
  __AppendElement(content, notice);
  __AppendElement(notice, createView(pageId, 'notice-dot'));
  appendText(
    notice,
    pageId,
    '建议 3—5 月出发，雨天记得给西湖留一把伞',
    'notice-text',
  );

  const sectionHeader = createView(pageId, 'section-header');
  __AppendElement(content, sectionHeader);
  appendText(sectionHeader, pageId, '每日路线', 'section-title');
  appendText(sectionHeader, pageId, '轻点卡片查看提示', 'section-caption');

  tripDays.forEach((item, index) => {
    const card = createView(pageId, 'day-card');
    const dayIndex = createView(pageId, 'day-index');
    const dayNumber = createView(pageId, 'day-number');
    const dayBody = createView(pageId, 'day-body');
    const topLine = createView(pageId, 'day-topline');
    const footer = createView(pageId, 'day-footer');

    __SetAttribute(card, 'aria-label', item.day + ' ' + item.title);
    __AppendElement(content, card);
    __AppendElement(card, dayIndex);
    __AppendElement(dayIndex, dayNumber);
    appendText(dayNumber, pageId, String(index + 1), 'day-number-text');
    __AppendElement(card, dayBody);
    __AppendElement(dayBody, topLine);
    appendText(topLine, pageId, item.title, 'day-title');
    appendText(topLine, pageId, item.mood, 'day-mood');
    appendText(dayBody, pageId, item.route, 'day-route');
    __AppendElement(dayBody, footer);
    appendText(footer, pageId, item.duration, 'day-duration');
    appendText(footer, pageId, item.transport, 'day-transport');

    bindTap(card, () => selectDay(card, item, index));
  });

  const selectionStatus = createView(pageId, 'selection-status');
  __AppendElement(content, selectionStatus);
  selectionStatusRawText = appendText(
    selectionStatus,
    pageId,
    '选择一天，获取当天的旅行提示',
    'selection-status-text',
  );

  appendText(
    content,
    pageId,
    '路线仅作示例 · 出发前请确认景区开放时间',
    'footnote',
  );
};

const mainThread = lynx.getCoreContext();
const engine = lynx.getEngine();

function onSelectTripDay(event) {
  const item = event.data;
  if (!item) return;

  const tips = [
    '傍晚 17:30 后到湖滨，晚霞和亮灯可以一起看。',
    '苏堤路程较长，建议从北向南骑行，午后在花港休息。',
    '灵隐寺尽量 8:00 前抵达，法喜寺请穿方便步行的鞋。',
    '水上巴士班次有限，建议提前确认武林门码头时刻。',
    '九溪石板路雨后湿滑，轻装徒步并预留返程时间。',
  ];

  mainThread.dispatchEvent({
    type: 'trip-day-selected',
    data: {
      message: item.day + ' 旅行提示：' + tips[item.index],
    },
  });
}

function cleanup() {
  mainThread.removeEventListener('select-trip-day', onSelectTripDay);
  engine.removeEventListener('__DestroyLifetime', cleanup);
}

mainThread.addEventListener('select-trip-day', onSelectTripDay);
engine.addEventListener('__DestroyLifetime', cleanup);
